import type {MobileShipment} from './mobileDelivery.js';
export type MobileEnvironmentInfo={schema:string;projectId:string;protocol:string;localOnly:boolean;mode?:'spark-msi';apiOrigin?:string;backendInstanceId?:string};
export type DriverSession={uid:string|null;scope:string|null;role:string|null;mode:'Signed out'|'Waiting'|'Driver'|'Recovery only';verifiedAtMs:number|null;online:boolean};
export type DriverPage={items:MobileShipment[];cursor:string|null;verifiedAtMs:number;cached:boolean};
export type PendingProof={evidenceId:string;name:string;operationId:string;state:string};
export type DriverDetail={shipment:MobileShipment;verifiedAtMs:number;cached:boolean;pendingProofs:PendingProof[];queuedStatus:string|null};
export type DriverDraft={fileId:string;name:string;contentType:string;bytes:number};
export type DriverQueueItem={operationId:string;shipmentId:string;action:string;label:string;state:string;reason:string|null;createdAtMs:number;attempts:number;canRetry:boolean;canDiscard:boolean;canCheck:boolean};
export type DriverQueue={items:DriverQueueItem[];cursor:number|null;pending:number;needsReview:number;drafts:DriverDraft[]};
export type DriverTracking={phase:'Stopped'|'Starting'|'Tracking'|'Expired'|'Needs review';reason:string|null;shipmentId:string|null;sessionId:string|null;lastCapturedAtMs:number|null;accuracy:number|null;sequence:number;leaseUntilMs:number|null};
export type MobileClient={environment():MobileEnvironmentInfo|null;state():DriverSession;initialize():Promise<DriverSession>;refreshSession():Promise<DriverSession>;signIn(email:string,password:string):Promise<DriverSession>;signOut():Promise<DriverSession>;readAssignments(input?:{cursor?:string|null}):Promise<DriverPage>;refreshAssignments(input?:{cursor?:string|null}):Promise<DriverPage>;readShipment(input:{shipmentId:string;refresh?:boolean}):Promise<DriverDetail>;readQueue(input?:{cursor?:number}):Promise<DriverQueue>;chooseProofFile():Promise<DriverDraft>;enqueueStatus(input:{shipmentId:string;status:string;notes:string;proofId:string|null}):Promise<{operationId:string;state:string}>;enqueueProof(input:{shipmentId:string;draftFileId:string}):Promise<{prepareOperationId:string;finaliseOperationId:string;evidenceId:string;name:string;state:string}>;readTracking():Promise<DriverTracking>;startTracking(input:{shipmentId:string}):Promise<DriverTracking>;stopTracking():Promise<DriverTracking>;retry(input:{operationId:string;checkOnly?:boolean}):Promise<{requested:true}>;discard(input:{operationId?:string;draftFileId?:string}):Promise<{discarded:true}>};
export function createMobileClient(input:{bridge:unknown;expectedEnvironment?:MobileEnvironmentInfo;openWebAuth:()=>Promise<{uid():string|null;signInToken(token:string):Promise<string>;signOut():Promise<void>}>}):MobileClient;
